-- Dr. Doudou : bibliothèque de sources et fiches (lecture seule), compteur de dépense IA.
-- Généré depuis supabase/knowledge/*.json — rejouable sans risque.
create table if not exists public.sources (id text primary key, publisher text not null, base_url text not null);
create table if not exists public.knowledge (id text primary key, titre text not null, mots text[] not null, resume text not null, source text not null references public.sources(id), url text not null, verifie date not null);
create table if not exists public.ai_usage (user_id uuid not null references auth.users(id) on delete cascade, day date not null, requests integer not null default 0, cost_usd numeric(10,6) not null default 0, primary key (user_id, day));
alter table public.sources enable row level security;
alter table public.knowledge enable row level security;
alter table public.ai_usage enable row level security;
drop policy if exists "sources: lecture" on public.sources;
create policy "sources: lecture" on public.sources for select to authenticated using (true);
drop policy if exists "knowledge: lecture" on public.knowledge;
create policy "knowledge: lecture" on public.knowledge for select to authenticated using (true);
drop policy if exists "ai_usage: sa consommation" on public.ai_usage;
create policy "ai_usage: sa consommation" on public.ai_usage for select to authenticated using (user_id = auth.uid());
revoke all on public.sources, public.knowledge, public.ai_usage from anon, authenticated;
grant select on public.sources, public.knowledge, public.ai_usage to authenticated;
grant select on public.sources, public.knowledge to service_role;
grant select, insert, update on public.ai_usage to service_role;

select (select count(*) from public.sources) as sources, (select count(*) from public.knowledge) as fiches, has_table_privilege('anon','public.knowledge','select') as anon_lit;
